    "friendsFlowText": "\u041e\u0442\u0432\u043e\u0440\u0435\u0442\u0435 DUVI, \u043a\u0430\u0436\u0435\u0442\u0435 \u043d\u0430 \u0430\u0441\u0438\u0441\u0442\u0435\u043d\u0442\u0430 \u043e\u0442 \u043a\u0430\u043a\u0432\u043e \u0438\u043c\u0430\u0442\u0435 \u043d\u0443\u0436\u0434\u0430 \u0438 \u0449\u0435 \u0431\u044a\u0434\u0435\u0442\u0435 \u043d\u0430\u0441\u043e\u0447\u0435\u043d\u0438 \u043a\u044a\u043c \u043d\u0430\u0439-\u0434\u043e\u0431\u0440\u0438\u044f \u043f\u043e\u043c\u043e\u0449\u043d\u0438\u043a.",
    "friendStep1": "\u0427\u0443\u0439\u0442\u0435 \u0435\u0434\u043d\u0430 \u043a\u0440\u0430\u0442\u043a\u0430 \u0444\u0440\u0430\u0437\u0430 \u0438 \u044f \u043f\u043e\u0432\u0442\u043e\u0440\u0435\u0442\u0435.",
    "friendStep2": "\u041d\u0430\u043f\u0440\u0430\u0432\u0435\u0442\u0435 \u043c\u0430\u043b\u044a\u043a \u0433\u043e\u0432\u043e\u0440\u0435\u043d \u0441\u043f\u0440\u0438\u043d\u0442 \u0438\u043b\u0438 \u0440\u043e\u043b\u0435\u0432\u0430 \u0438\u0433\u0440\u0430.",
    "friendStep3": "\u041a\u043e\u0440\u0438\u0433\u0438\u0440\u0430\u0439\u0442\u0435 \u0435\u0434\u043d\u0430 \u0433\u0440\u0435\u0448\u043a\u0430 \u0438 \u043e\u0431\u044f\u0441\u043d\u0435\u0442\u0435 \u043f\u0440\u0430\u0432\u0438\u043b\u043e\u0442\u043e.",
    "friendStep4": "\u0412\u0437\u0435\u043c\u0435\u0442\u0435 \u043c\u0438\u043d\u0438 \u0438\u0441\u0442\u043e\u0440\u0438\u044f \u0441 \u043b\u0435\u0441\u0435\u043d \u0440\u0435\u0447\u043d\u0438\u043a.",
    "friendStep5": "\u0417\u0430\u0449\u0438\u0442\u0435\u0442\u0435 \u043f\u043e\u0440\u0435\u0434\u0438\u0446\u0430\u0442\u0430 \u0438 \u043d\u0430\u0433\u0440\u0430\u0434\u0435\u0442\u0435 \u043f\u0440\u043e\u0433\u0440\u0435\u0441\u0430.",
    "friendStep6": "\u041f\u043e\u0434\u0433\u043e\u0442\u0432\u0435\u0442\u0435 \u0441\u0435 \u0437\u0430 \u0433\u043e\u0432\u043e\u0440\u0435\u043d\u0435 \u043d\u0430 \u0438\u0437\u043f\u0438\u0442\u0430 \u0438 \u043f\u043e-\u0434\u043e\u0431\u0440\u0438 \u043e\u0442\u0433\u043e\u0432\u043e\u0440\u0438.",
    "friendStep7": "\u041f\u0440\u0430\u043a\u0442\u0438\u043a\u0443\u0432\u0430\u0439\u0442\u0435 \u0433\u043e\u0432\u043e\u0440\u0435\u043d\u0435 \u043d\u0430 \u0436\u0438\u0432\u043e \u0441 \u0442\u043e\u043f\u043b\u043e \u0440\u044a\u043a\u043e\u0432\u043e\u0434\u0441\u0442\u0432\u043e.",
    "linaRole": "\u0413\u043e\u0432\u043e\u0440\u0435\u0449 \u043f\u0440\u0438\u044f\u0442\u0435\u043b",
    "linaText": "\u041a\u0440\u0430\u0442\u043a\u0438 \u0434\u0438\u0430\u043b\u043e\u0437\u0438, \u0440\u043e\u043b\u0435\u0432\u0438 \u0438\u0433\u0440\u0438, \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043a\u0438 \u0437\u0430 \u0443\u0432\u0435\u0440\u0435\u043d\u043e\u0441\u0442 \u0438 \u043f\u044a\u0440\u0432\u0438\u0442\u0435 \u0434\u0443\u043c\u0438 \u043d\u0430 \u0433\u043b\u0430\u0441 \u043e\u0442 \u043f\u044a\u0440\u0432\u0438\u044f \u0434\u0435\u043d.",
    "gramiRole": "\u041f\u0440\u0438\u044f\u0442\u0435\u043b \u043f\u043e \u0433\u0440\u0430\u043c\u0430\u0442\u0438\u043a\u0430",
    "gramiText": "\u041f\u0440\u043e\u0441\u0442\u0438 \u043a\u043e\u0440\u0435\u043a\u0446\u0438\u0438, \u0433\u0440\u0430\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u043c\u043e\u0434\u0435\u043b\u0438, \u0447\u043b\u0435\u043d\u043e\u0432\u0435, \u0433\u043b\u0430\u0433\u043e\u043b\u043d\u0438 \u0444\u043e\u0440\u043c\u0438 \u0438 \u044f\u0441\u043d\u0438 \u043e\u0431\u044f\u0441\u043d\u0435\u043d\u0438\u044f \u043d\u0430 \u0441\u043b\u0435\u0434\u0432\u0430\u0449\u0430\u0442\u0430 \u0441\u0442\u044a\u043f\u043a\u0430.",
    "stellaRole": "\u0418\u0441\u0442\u043e\u0440\u0438\u044f \u043f\u0440\u0438\u044f\u0442\u0435\u043b",
