    "novaRole": "\u041f\u0440\u043e\u0438\u0437\u043d\u043e\u0448\u0435\u043d\u0438\u0435 \u043f\u0440\u0438\u044f\u0442\u0435\u043b",
    "novaText": "\u041f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u0437\u0430 \u0441\u043b\u0443\u0448\u0430\u043d\u0435, \u0437\u0432\u0443\u043a\u043e\u0432\u0438 \u043f\u0440\u0430\u043a\u0442\u0438\u043a\u0438, \u0443\u043f\u0440\u0430\u0436\u043d\u0435\u043d\u0438\u044f \u0437\u0430 \u043f\u043e\u0432\u0442\u043e\u0440\u0435\u043d\u0438\u0435 \u0441\u043b\u0435\u0434 \u043c\u0435\u043d \u0438 \u0440\u0430\u0431\u043e\u0442\u0430 \u0441 \u043f\u0440\u043e\u0438\u0437\u043d\u043e\u0448\u0435\u043d\u0438\u0435\u0442\u043e \u0444\u0440\u0430\u0437\u0430 \u043f\u043e \u0444\u0440\u0430\u0437\u0430.",
    "motiRole": "\u041c\u043e\u0442\u0438\u0432\u0430\u0446\u0438\u043e\u043d\u0435\u043d \u043f\u0440\u0438\u044f\u0442\u0435\u043b",
