    "elsaRole": "\u0418\u0437\u043f\u0438\u0442 \u043f\u0440\u0438\u044f\u0442\u0435\u043b",
    "elsaAppRole": "\u0418\u0437\u043f\u0438\u0442\u0432\u0430\u0449",
    "elsaText": "B1/B2 \u043f\u043e\u0434\u043a\u0430\u043d\u0438 \u0437\u0430 \u0433\u043e\u0432\u043e\u0440\u0435\u043d\u0435, \u043f\u043e-\u0434\u043e\u0431\u0440\u0438 \u043e\u0442\u0433\u043e\u0432\u043e\u0440\u0438, \u0443\u0432\u0435\u0440\u0435\u043d\u043e\u0441\u0442 \u043d\u0430 \u0438\u0437\u043f\u0438\u0442\u0430, \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0438\u0440\u0430\u043d\u0430 \u043f\u0440\u0430\u043a\u0442\u0438\u043a\u0430 \u0437\u0430 \u0443\u0441\u0442\u0435\u043d \u0438\u0437\u043f\u0438\u0442 \u0438 \u044f\u0441\u043d\u0430 \u043e\u0431\u0440\u0430\u0442\u043d\u0430 \u0432\u0440\u044a\u0437\u043a\u0430.",
    "sofiaRole": "\u0416\u0438\u0432/\u0433\u043e\u0432\u043e\u0440\u0435\u0449 \u043f\u0440\u0438\u044f\u0442\u0435\u043b",
    "sofiaAppRole": "\u0420\u0430\u0437\u0433\u043e\u0432\u043e\u0440",
    "sofiaText": "\u041f\u0440\u0430\u043a\u0442\u0438\u043a\u0443\u0432\u0430\u043d\u0435 \u043d\u0430 \u0433\u043e\u0432\u043e\u0440\u0435\u043d\u0435 \u043d\u0430 \u0436\u0438\u0432\u043e, \u0435\u0436\u0435\u0434\u043d\u0435\u0432\u043d\u043e \u0440\u044a\u043a\u043e\u0432\u043e\u0434\u0441\u0442\u0432\u043e, \u0442\u043e\u043f\u044a\u043b \u0440\u0430\u0437\u0433\u043e\u0432\u043e\u0440, \u043d\u0435\u0436\u043d\u043e \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u0435 \u0438 \u0438\u0437\u0433\u0440\u0430\u0436\u0434\u0430\u043d\u0435 \u043d\u0430 \u0443\u0432\u0435\u0440\u0435\u043d\u043e\u0441\u0442.",
    "teachersKicker": "\u041f\u0443\u0431\u043b\u0438\u0447\u043d\u0438 \u043f\u0440\u043e\u0444\u0438\u043b\u0438",
    "teachersTitle": "\u0417\u0430\u043f\u043e\u0437\u043d\u0430\u0439\u0442\u0435 \u0441\u0435 \u0441 \u0443\u0447\u0438\u0442\u0435\u043b\u0438, \u043a\u043e\u0438\u0442\u043e \u0441\u0430 <span class=\"grad-text\">\u0432 Duvela</span>",
