    "teacherLoadingTitle": "\u0417\u0430\u0440\u0435\u0436\u0434\u0430\u043d\u0435 \u043d\u0430 \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u0438 \u043f\u0440\u043e\u0444\u0438\u043b\u0438 \u043d\u0430 \u0443\u0447\u0438\u0442\u0435\u043b\u0438",
    "teacherLoadingText": "Duvela \u043f\u043e\u043a\u0430\u0437\u0432\u0430 \u0441\u0430\u043c\u043e \u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u044f \u0437\u0430 \u043f\u0440\u043e\u0444\u0438\u043b\u0430, \u043a\u043e\u044f\u0442\u043e \u0443\u0447\u0438\u0442\u0435\u043b\u0438\u0442\u0435 \u043f\u0443\u0431\u043b\u0438\u043a\u0443\u0432\u0430\u0442 \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u043e.",
