    "pricingSub": "Duvela \u043d\u0435 \u0438\u0437\u043c\u0438\u0441\u043b\u044f \u0446\u0435\u043d\u0430 \u043d\u0430 \u0435\u0434\u043d\u0430 \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u0430 \u0437\u0430 \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u0438 \u0443\u0447\u0438\u0442\u0435\u043b\u0438. \u0412\u0441\u0435\u043a\u0438 \u043f\u043b\u0430\u0442\u0435\u043d \u0443\u0440\u043e\u043a, \u043a\u0443\u0440\u0441 \u0438\u043b\u0438 \u0441\u044a\u0431\u0438\u0442\u0438\u0435 \u043f\u043e\u043a\u0430\u0437\u0432\u0430 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u0430 \u0446\u0435\u043d\u0430 \u043f\u0440\u0435\u0434\u0438 \u043f\u043b\u0430\u0449\u0430\u043d\u0435.",
    "price1Kicker": "\u041e\u0431\u0443\u0447\u0430\u0435\u043c",
    "price1Title": "\u0411\u0435\u0437\u043f\u043b\u0430\u0442\u0435\u043d \u0441\u0442\u0430\u0440\u0442",
