    "gramiRole": "\u0413\u0440\u0430\u043c\u043c\u0430\u0442\u0438\u043a\u0430, \u043f\u0440\u0438\u044f\u0442\u0435\u043b\u044c",
    "gramiText": "\u041f\u0440\u043e\u0441\u0442\u044b\u0435 \u0438\u0441\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f, \u0433\u0440\u0430\u043c\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0448\u0430\u0431\u043b\u043e\u043d\u044b, \u0430\u0440\u0442\u0438\u043a\u043b\u0438, \u0444\u043e\u0440\u043c\u044b \u0433\u043b\u0430\u0433\u043e\u043b\u043e\u0432 \u0438 \u0447\u0435\u0442\u043a\u0438\u0435 \u043e\u0431\u044a\u044f\u0441\u043d\u0435\u043d\u0438\u044f \u043f\u043e\u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0438\u0445 \u0448\u0430\u0433\u043e\u0432.",
    "stellaRole": "\u0418\u0441\u0442\u043e\u0440\u0438\u044f, \u043f\u0440\u0438\u044f\u0442\u0435\u043b\u044c",
    "stellaText": "\u041c\u0438\u043a\u0440\u043e\u0438\u0441\u0442\u043e\u0440\u0438\u0438, \u043f\u0440\u043e\u0441\u0442\u044b\u0435 \u0441\u0446\u0435\u043d\u044b \u0438 \u043a\u043e\u0440\u043e\u0442\u043a\u0438\u0435 \u0434\u0438\u0430\u043b\u043e\u0433\u0438, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u044e\u0442 \u0441\u043b\u043e\u0432\u0430\u0440\u043d\u044b\u0439 \u0437\u0430\u043f\u0430\u0441 \u0432 \u043f\u0430\u043c\u044f\u0442\u044c.",
    "novaRole": "\u041f\u0440\u043e\u0438\u0437\u043d\u043e\u0448\u0435\u043d\u0438\u0435, \u043f\u0440\u0438\u044f\u0442\u0435\u043b\u044c",
    "novaText": "\u041f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0430\u0443\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f, \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043a\u0430 \u0437\u0432\u0443\u043a\u043e\u0432, \u0443\u043f\u0440\u0430\u0436\u043d\u0435\u043d\u0438\u044f \u00ab\u043f\u043e\u0432\u0442\u043e\u0440\u044f\u0439 \u0437\u0430 \u043c\u043d\u043e\u0439\u00bb \u0438 \u0440\u0430\u0431\u043e\u0442\u0430 \u043d\u0430\u0434 \u043f\u0440\u043e\u0438\u0437\u043d\u043e\u0448\u0435\u043d\u0438\u0435\u043c \u0444\u0440\u0430\u0437\u0430 \u0437\u0430 \u0444\u0440\u0430\u0437\u043e\u0439.",
    "motiRole": "\u041c\u043e\u0442\u0438\u0432\u0430\u0446\u0438\u044f, \u043f\u0440\u0438\u044f\u0442\u0435\u043b\u044c",
    "motiText": "\u041f\u043e\u043b\u043d\u0430\u044f \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0430, \u043d\u0430\u0433\u0440\u0430\u0434\u044b, \u043f\u043e\u043e\u0449\u0440\u0435\u043d\u0438\u0435, \u043c\u0438\u043d\u0438-\u0438\u0441\u043f\u044b\u0442\u0430\u043d\u0438\u044f \u0438 \u043e\u0447\u0435\u0440\u0435\u0434\u043d\u0430\u044f \u043c\u0430\u043b\u0435\u043d\u044c\u043a\u0430\u044f \u043f\u043e\u0431\u0435\u0434\u0430, \u0437\u0430 \u043a\u043e\u0442\u043e\u0440\u043e\u0439 \u0441\u0442\u043e\u0438\u0442 \u0433\u043e\u043d\u044f\u0442\u044c\u0441\u044f.",
    "elsaRole": "\u041f\u0440\u0438\u044f\u0442\u0435\u043b\u044c \u043f\u043e \u044d\u043a\u0437\u0430\u043c\u0435\u043d\u0443",
    "elsaAppRole": "\u042d\u043a\u0441\u043f\u0435\u0440\u0442",
    "elsaText": "B1/B2 \u0420\u0435\u0447\u0435\u0432\u044b\u0435 \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0438, \u043b\u0443\u0447\u0448\u0438\u0435 \u043e\u0442\u0432\u0435\u0442\u044b, \u0443\u0432\u0435\u0440\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u043d\u0430 \u044d\u043a\u0437\u0430\u043c\u0435\u043d\u0435, \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u043f\u0440\u0430\u043a\u0442\u0438\u043a\u0430 \u0443\u0441\u0442\u043d\u043e\u0433\u043e \u044d\u043a\u0437\u0430\u043c\u0435\u043d\u0430 \u0438 \u0447\u0435\u0442\u043a\u0430\u044f \u043e\u0431\u0440\u0430\u0442\u043d\u0430\u044f \u0441\u0432\u044f\u0437\u044c.",
    "sofiaRole": "\u0416\u0438\u0432\u043e\u0439/\u0433\u043e\u0432\u043e\u0440\u044f\u0449\u0438\u0439 \u043f\u0440\u0438\u044f\u0442\u0435\u043b\u044c",
    "sofiaAppRole": "\u0420\u0430\u0437\u0433\u043e\u0432\u043e\u0440",
    "sofiaText": "\u0420\u0430\u0437\u0433\u043e\u0432\u043e\u0440\u043d\u0430\u044f \u043f\u0440\u0430\u043a\u0442\u0438\u043a\u0430 \u0432\u0436\u0438\u0432\u0443\u044e, \u0435\u0436\u0435\u0434\u043d\u0435\u0432\u043d\u043e\u0435 \u0440\u0443\u043a\u043e\u0432\u043e\u0434\u0441\u0442\u0432\u043e, \u0442\u0435\u043f\u043b\u044b\u0435 \u0431\u0435\u0441\u0435\u0434\u044b, \u043c\u044f\u0433\u043a\u0438\u0439 \u043a\u043e\u0443\u0447\u0438\u043d\u0433 \u0438 \u0443\u043a\u0440\u0435\u043f\u043b\u0435\u043d\u0438\u0435 \u0443\u0432\u0435\u0440\u0435\u043d\u043d\u043e\u0441\u0442\u0438.",
    "teachersKicker": "\u041f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u0435 \u043f\u0440\u043e\u0444\u0438\u043b\u0438",
    "teachersTitle": "\u041f\u043e\u0437\u043d\u0430\u043a\u043e\u043c\u044c\u0442\u0435\u0441\u044c \u0441 \u0443\u0447\u0438\u0442\u0435\u043b\u044f\u043c\u0438, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 <span class=\"grad-text\">\u043d\u0430 Duvela</span>",
    "teachersSub": "\u0412 \u044d\u0442\u043e\u043c \u0440\u0430\u0437\u0434\u0435\u043b\u0435 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0442\u0441\u044f \u043e\u0431\u0449\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b\u0435 \u043f\u0440\u043e\u0444\u0438\u043b\u0438 \u0443\u0447\u0438\u0442\u0435\u043b\u0435\u0439 \u0438\u0437 Duvela. \u041d\u0438\u043a\u0430\u043a\u0438\u0445 \u0432\u044b\u0431\u043e\u0440\u043e\u0447\u043d\u044b\u0445 \u0440\u0435\u0439\u0442\u0438\u043d\u0433\u043e\u0432, \u043a\u043e\u043b\u0438\u0447\u0435\u0441\u0442\u0432\u0430 \u043f\u043e\u0434\u043f\u0438\u0441\u0447\u0438\u043a\u043e\u0432 \u0438\u043b\u0438 \u0432\u044b\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u044b\u0445 \u043e\u0442\u0437\u044b\u0432\u043e\u0432.",
    "teacherLoadingTitle": "\u0417\u0430\u0433\u0440\u0443\u0437\u043a\u0430 \u043e\u0431\u0449\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b\u0445 \u043f\u0440\u043e\u0444\u0438\u043b\u0435\u0439 \u0443\u0447\u0438\u0442\u0435\u043b\u0435\u0439",
    "teacherLoadingText": "Duvela \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u044e \u043f\u0440\u043e\u0444\u0438\u043b\u044f, \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u0443\u0447\u0438\u0442\u0435\u043b\u044f \u043f\u0443\u0431\u043b\u0438\u043a\u0443\u044e\u0442 \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u043e.",
