    "friendStep2": "\u0421\u043f\u0440\u0438\u043d\u0442 \u0451 \u0431\u043e\u0437\u0438\u0438 \u043d\u0430\u049b\u0448\u04b3\u043e\u0438 \u043d\u043e\u0447\u0438\u0437\u0440\u043e \u0438\u04b7\u0440\u043e \u043a\u0443\u043d\u0435\u0434.",
    "friendStep3": "\u042f\u043a \u0445\u0430\u0442\u043e\u0433\u0438\u0440\u043e \u0438\u0441\u043b\u043e\u04b3 \u043a\u0443\u043d\u0435\u0434 \u0432\u0430 \u049b\u043e\u0438\u0434\u0430\u0440\u043e \u0448\u0430\u0440\u04b3 \u0434\u0438\u04b3\u0435\u0434.",
    "friendStep4": "\u0411\u043e \u043b\u0443\u0493\u0430\u0442\u0438 \u043e\u0441\u043e\u043d \u044f\u043a \u04b3\u0438\u043a\u043e\u044f\u0438 \u0445\u0443\u0440\u0434 \u0433\u0438\u0440\u0435\u0434.",
    "friendStep5": "\u04b2\u0438\u0444\u0437 \u043a\u0430\u0440\u0434\u0430\u043d\u0438 \u0445\u0430\u0442\u0438 \u043f\u0430\u0439\u043c\u043e\u0438\u0448 \u0432\u0430 \u043c\u0443\u043a\u043e\u0444\u043e\u0442\u043e\u043d\u0438\u0434\u0430\u043d\u0438 \u043f\u0435\u0448\u0440\u0430\u0444\u0442.",
    "friendStep6": "\u0411\u0430 \u0441\u0443\u0445\u0430\u043d\u0440\u043e\u043d\u0438\u0438 \u0438\u043c\u0442\u0438\u04b3\u043e\u043d\u04e3 \u0432\u0430 \u04b7\u0430\u0432\u043e\u0431\u04b3\u043e\u0438 \u0431\u0435\u04b3\u0442\u0430\u0440 \u043e\u043c\u043e\u0434\u0430 \u0448\u0430\u0432\u0435\u0434.",
    "friendStep7": "\u0411\u043e \u0434\u0430\u0441\u0442\u0443\u0440\u0438 \u0433\u0430\u0440\u043c \u0441\u0443\u0445\u0430\u043d \u0433\u0443\u0444\u0442\u0430\u043d\u0440\u043e \u043c\u0430\u0448\u049b \u043a\u0443\u043d\u0435\u0434.",
