    "gramiText": "\u0418\u0441\u043b\u043e\u04b3\u04b3\u043e\u0438 \u043e\u0434\u0434\u04e3, \u043d\u0430\u043c\u0443\u043d\u0430\u04b3\u043e\u0438 \u0433\u0440\u0430\u043c\u043c\u0430\u0442\u0438\u043a\u04e3, \u043c\u0430\u049b\u043e\u043b\u0430\u04b3\u043e, \u0448\u0430\u043a\u043b\u04b3\u043e\u0438 \u0444\u0435\u044a\u043b \u0432\u0430 \u0442\u0430\u0432\u0437\u0435\u04b3\u043e\u0442\u0438 \u0440\u0430\u0432\u0448\u0430\u043d\u0438 \u049b\u0430\u0434\u0430\u043c\u0438 \u043e\u044f\u043d\u0434\u0430.",
    "stellaRole": "\u0414\u04ef\u0441\u0442\u0438 \u04b3\u0438\u043a\u043e\u044f",
